insert into public.vow_knowledge
  (domain, topic, title, content, principles, recommended_actions, metrics, cautions, active)
values
  ('learning','skill_acquisition','Beginner skill progression','For a new practical or creative skill, establish the learner baseline and desired real-world outcome. Teach minimum foundations first, then progressively harder practice, application and checkpoints. If no experience is provided, treat the starting point as Level 1 beginner.','["Establish baseline","Break skills into prerequisite subskills","Move from guided practice to independent application","Increase difficulty only after the current stage is reliable","Use checkpoints to decide whether to progress"]'::jsonb,'["Ask about prior experience","Ask the desired outcome","Ask about time and constraints","Teach foundational skills","Use a small real-world application","Review at milestones"]'::jsonb,'["skills_mastered","successful_repetitions","practice_sessions","completed_applications","project_completion"]'::jsonb,'["Do not assume expertise","Do not make every day identical","Do not increase difficulty merely because a new week started"]'::jsonb,true),
  ('learning','skill_acquisition','Unknown-skill baseline','When a user says learn, master, improve or become able to do something but gives no baseline, use a Level 1 beginner plan. Start with terminology, equipment or environment orientation, basic technique and a small success criterion before advanced work.','["Start with prerequisites","Use short controlled exercises","Define observable success","Delay advanced techniques until foundations are stable"]'::jsonb,'["Establish the simplest baseline","Give a concrete first exercise","Check understanding or execution","Repeat with a small increase in difficulty"]'::jsonb,'["first_skill_completed","successful_repetitions","practice_consistency","foundation_checkpoint"]'::jsonb,'["Never fabricate a user baseline","Avoid overwhelming beginners"]'::jsonb,true),
  ('creative','crafts','Craft and making progression','Craft goals such as crochet, knitting, sewing, pottery, woodworking or model making should progress from materials and terminology to basic techniques, controlled exercises, combining techniques, a guided project and an independent project.','["Learn tools before complex construction","Practise individual techniques","Combine techniques after prerequisites","Use progressively harder projects"]'::jsonb,'["Identify tools and materials","Practise a foundational technique","Complete a small sample","Follow a beginner project","Create a small independent project"]'::jsonb,'["techniques_mastered","practice_sessions","samples_completed","projects_completed"]'::jsonb,'["Use appropriate safety guidance","Do not jump directly to complex projects"]'::jsonb,true),
  ('creative','photography','Photography progression','Photography goals should move from camera or phone controls and composition fundamentals into focused shooting exercises, review, editing and a coherent final photo set. Adapt to equipment and intended style.','["Learn one control at a time","Practise composition deliberately","Review results","Apply techniques in varied conditions"]'::jsonb,'["Establish equipment baseline","Practise focus and exposure","Shoot a constrained exercise","Review a small set","Complete a themed set"]'::jsonb,'["shoots_completed","selected_images","technical_exercises","photo_set_completion"]'::jsonb,'["Do not assume professional equipment","Avoid treating gear purchases as progress"]'::jsonb,true),
  ('creative','music','Instrument and music progression','Music goals should progress from setup and basic technique to rhythm or notation where relevant, controlled exercises, short pieces, transitions and independent performance or creation.','["Prioritise clean fundamentals","Practise difficult sections slowly","Connect drills to real music","Increase complexity after control is reliable"]'::jsonb,'["Establish instrument baseline","Practise one foundation","Learn a short section","Connect sections","Perform or record a complete piece"]'::jsonb,'["practice_sessions","clean_repetitions","pieces_started","pieces_completed","performance_runs"]'::jsonb,'["Avoid repetitive practice when technique deteriorates","Do not equate speed with mastery"]'::jsonb,true),
  ('practical','cooking','Cooking skill progression','Cooking goals should progress from kitchen setup and basic safety to core techniques, simple dishes, combining techniques and increasingly independent meals. Adapt to equipment, cuisine and intended outcome.','["Master core techniques before complex recipes","Use small dishes for practice","Increase independence gradually","Review results and adjust technique"]'::jsonb,'["Establish kitchen baseline","Practise a basic technique","Cook a simple dish","Combine techniques","Complete a meal independently"]'::jsonb,'["techniques_mastered","dishes_completed","practice_sessions","successful_meals"]'::jsonb,'["Follow appropriate food safety guidance","Do not assume access to specific equipment"]'::jsonb,true),
  ('languages','language_learning','Language acquisition progression','Language goals should progress through high-value vocabulary and pronunciation into sentence formation, listening and reading comprehension, guided speaking and writing, then increasingly independent real-world use. Personalise by language, current level and intended use.','["Use the language actively","Space practice","Connect vocabulary to context","Balance input and output","Track recurring errors"]'::jsonb,'["Establish current level","Build high-frequency vocabulary","Practise short sentences","Add listening and speaking","Use realistic tasks"]'::jsonb,'["vocabulary_retained","comprehension_accuracy","speaking_minutes","writing_tasks","recurring_errors"]'::jsonb,'["Do not reduce language learning to vocabulary lists","Do not assume proficiency without asking"]'::jsonb,true),
  ('technology','programming','Programming skill progression','Programming goals should move from environment setup and core concepts into small exercises, debugging, a focused project, testing and shipping. Adapt to language, framework and desired application.','["Learn by building","Keep exercises small","Treat debugging as learning","Test behaviour","Ship increments"]'::jsonb,'["Establish tooling baseline","Build tiny programs","Debug deliberately","Implement a focused feature","Test and ship"]'::jsonb,'["concepts_demonstrated","features_completed","bugs_fixed","tests_passing","projects_shipped"]'::jsonb,'["Do not copy code without understanding","Never place secrets in client source"]'::jsonb,true),
  ('communication','public_speaking','Communication skill progression','Public speaking, presenting and debate goals should progress from message structure and short practice to timed rehearsals, feedback and a complete delivery.','["Clarify the message","Practise aloud","Increase audience and duration gradually","Use feedback"]'::jsonb,'["Define the message","Deliver a short version","Rehearse","Practise with a small audience","Deliver the full presentation"]'::jsonb,'["rehearsals","delivery_duration","feedback_items","complete_deliveries"]'::jsonb,'["Do not require memorising every word","Keep progression realistic"]'::jsonb,true),
  ('sports','skill_sports','Sports skill progression','Skill-based sports should progress from safety, equipment and movement fundamentals into isolated technique, controlled drills, variable practice, game or real-world application and performance review. Endurance sports additionally need workload progression and recovery.','["Establish experience baseline","Teach foundational technique","Use controlled repetition","Apply under realistic constraints","Review performance"]'::jsonb,'["Ask about experience and access","Practise a fundamental","Use a controlled drill","Increase complexity","Apply in realistic conditions"]'::jsonb,'["sessions_completed","skill_checkpoints","successful_repetitions","performance_notes"]'::jsonb,'["Use appropriate supervision and safety","Avoid sudden workload increases"]'::jsonb,true),
  ('projects','project_execution','Outcome-to-deliverable progression','Projects should convert the desired outcome into dependencies and concrete deliverables, progressing from definition and setup to the smallest useful output, iteration, quality checks and completion.','["Define the finished outcome","Identify dependencies","Ship small increments","Review evidence","Finish before expanding scope"]'::jsonb,'["Write acceptance criteria","Break into deliverables","Schedule the first useful output","Review blockers","Verify the final outcome"]'::jsonb,'["deliverables_completed","milestones_completed","blocked_items","acceptance_criteria_met"]'::jsonb,'["Do not create activity for activity sake","Avoid scope that does not serve the outcome"]'::jsonb,true)
